function Chart({rows,low=18,high=38,compact=false,repairAt}:{rows:Reading[];low?:number;high?:number;compact?:boolean;repairAt?:number}){
 const [hover,setHover]=useState<number|null>(null);const width=960,height=compact?75:238,pad=compact?3:32,bottom=compact?3:30;const max=Math.max(high*1.6,...rows.filter(r=>r.value!==null&&r.quality==='valid').map(r=>r.value!))*1.15;
 const x=(j:number)=>pad+j/Math.max(1,rows.length-1)*(width-pad-12);const y=(v:number)=>height-bottom-v/max*(height-bottom-12);
 const segments:Reading[][]=[];let segment:Reading[]=[];for(const r of rows){if(r.value!==null&&r.quality==='valid')segment.push(r);else if(segment.length){segments.push(segment);segment=[];}}if(segment.length)segments.push(segment);
 const line=(s:Reading[])=>s.map((r,j)=>`${j?'L':'M'}${x(rows.indexOf(r)).toFixed(1)},${y(r.value!).toFixed(1)}`).join(' ');
 const hovered=hover===null?null:rows[hover];
 return <div className={`chart ${compact?'compact':''}`}>
 <svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label="Simulated water consumption in litres per minute; shaded band shows expected range" onMouseMove={e=>{const rect=e.currentTarget.getBoundingClientRect();setHover(Math.max(0,Math.min(rows.length-1,Math.round(((e.clientX-rect.left)/rect.width*width-pad)/(width-pad-12)*(rows.length-1)))));}} onMouseLeave={()=>setHover(null)}>
 <defs><linearGradient id={compact?'mini-fill':'chart-fill'} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#5ad6b1" stopOpacity=".15"/><stop offset="100%" stopColor="#5ad6b1" stopOpacity="0"/></linearGradient></defs>
 {!compact&&[0,40,80,120,160].filter(v=>v<max).map(v=><g key={v}><line x1={pad} x2={width-10} y1={y(v)} y2={y(v)} stroke="#242a2a" strokeDasharray="3 5"/><text x="0" y={y(v)+4} fill="#757e7c" fontSize="10">{v}</text></g>)}
 <rect x={pad} width={width-pad-12} y={y(high)} height={y(low)-y(high)} fill="#6c9f8b" opacity=".075"/><line x1={pad} x2={width-12} y1={y(high)} y2={y(high)} stroke="#7eae98" strokeDasharray="4 6" opacity=".35"/>
 {segments.map((s,j)=><g key={j}><path d={`${line(s)} L${x(rows.indexOf(s.at(-1)!))},${height-bottom} L${x(rows.indexOf(s[0]))},${height-bottom} Z`} fill={`url(#${compact?'mini-fill':'chart-fill'})`}/><path d={line(s)} fill="none" stroke="#70ddb9" strokeWidth={compact?2.4:2} vectorEffect="non-scaling-stroke"/></g>)}
 {repairAt&&rows.some(r=>r.at>=repairAt)&&<line x1={x(rows.findIndex(r=>r.at>=repairAt))} x2={x(rows.findIndex(r=>r.at>=repairAt))} y1="10" y2={height-bottom} stroke="#c6a8eb" strokeDasharray="4 4"/>}
 {!compact&&rows.length>0&&Array.from({length:7},(_,j)=>Math.round(j/6*(rows.length-1))).map((idx,j)=><text key={j} x={x(idx)} y={height-5} textAnchor={j===0?'start':j===6?'end':'middle'} fill="#818b88" fontSize="10">{time(rows[idx].at)}</text>)}
 {hovered&&!compact&&<g><line x1={x(hover!)} x2={x(hover!)} y1="10" y2={height-bottom} stroke="#7d9189" strokeDasharray="3 3"/>{hovered.value!==null&&hovered.quality==='valid'&&<circle cx={x(hover!)} cy={y(hovered.value)} r="4" fill="#a0f1d5"/>}</g>}
 </svg>{hovered&&!compact&&<div className="chart-tooltip">{time(hovered.at)} · {hovered.value===null||hovered.quality!=='valid'?'No valid reading':`${hovered.value} L/min`}</div>}
 </div>;
}
