 if(loginRequired)return <main className="login-page"><section className="login-brand"><span className="sim-badge">SIMULATION / FICTIONAL CAMPUS</span><h1>LEAK<br/>LOOP.</h1><p>Campus water operations.<br/>Evidence before action.</p></section><form className="login-form" onSubmit={e=>{if(!authConfig.passwordLogin){e.preventDefault();return;}void signIn(e);}}><span className="eyebrow">EVERGREEN CAMPUS / SECURE ACCESS</span><h2>Sign in to<br/>your workspace.</h2><p>Your account determines which records and actions you can access.</p>{error&&<div className="notice error" role="alert">{error}</div>}{authConfig.sso&&<a className="primary full sso-button" href="/api/auth/sso/start"><ShieldCheck size={15}/>Continue with {authConfig.sso.name}<ArrowRight size={14}/></a>}{authConfig.passwordLogin&&<><label className="field">Email<input type="email" autoComplete="username" required maxLength={254} value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@evergreen.local"/></label><label className="field">Password<input type="password" autoComplete="current-password" required maxLength={256} value={password} onChange={e=>setPassword(e.target.value)}/></label><button className="primary full" disabled={busy}>{busy?<Loader2 size={15} className="spin"/>:<ShieldCheck size={15}/>}Sign in<ArrowRight size={14}/></button>{authConfig.passwordRecovery&&<a className="text-button" href="/account?flow=forgot">Forgot password?</a>}</>}{demoLogin&&<button type="button" className="secondary full" disabled={busy} onClick={()=>void identity('manager')}>Enter labelled demo</button>}<div className="login-note"><ShieldCheck size={15}/>Account permissions are checked by the server. Operational telemetry remains simulated.</div></form></main>;
