 const i=s.incidents[0];const building=s.buildings.find(b=>b.id===i.buildingId)!;const work=s.workOrders.find(w=>w.incidentId===i.id);const selectedWork=s.workOrders.find(w=>w.id===focusWork)||s.workOrders.find(w=>w.techId===actor?.id)||work;
 const chartB=s.buildings.find(b=>b.id===chartBuilding)!;const active=s.incidents.filter(i=>i.state!=='Closed');const pending=s.incidents.filter(i=>i.proposal?.status==='pending');const isManager=actor?.role==='manager';const isOperator=actor?.role==='operator';
 const latest=(bid:string)=>s.readings.filter(r=>r.buildingId===bid).at(-1);const value=(bid:string)=>{const r=latest(bid);return r&&r.quality==='valid'&&r.value!==null&&s.now-r.at<=1200000?r.value:null;};const total=s.buildings.reduce((a,b)=>a+(value(b.id)??0),0);const completeCoverage=s.buildings.every(b=>value(b.id)!==null);
