 const incidentTable=<div className="table-wrap"><table><thead><tr><th>INCIDENT / LOCATION</th><th>OBSERVATION</th><th>WORKFLOW STATUS</th><th>DETECTED</th><th/></tr></thead><tbody>{s.incidents.filter(x=>`${x.id} ${x.title} ${building.name}`.toLowerCase().includes(filter.toLowerCase())).map(x=><tr key={x.id} onClick={()=>go('incidents')} tabIndex={0} onKeyDown={e=>{if(e.key==='Enter')go('incidents');}}><td><span className="incident-title"><span className="warning-mark"><CircleAlert size={17}/></span><div><strong>{x.title}</strong><small>{x.id} <span>·</span> {building.name}</small></div></span></td><td><span className="mono">{value(x.buildingId)===null?'Telemetry gap':`${value(x.buildingId)} L/min`}</span><small>{x.hypothesis==='Scheduled usage'?'Schedule explains demand':'Expected 18–38 L/min'}</small></td><td><Badge tone={x.state==='Closed'?'green':x.state==='Detected'?'amber':'cyan'}>{x.state}</Badge></td><td className="mono muted">{time(x.detectedAt)}</td><td><ChevronRight size={16}/></td></tr>)}</tbody></table></div>;
